import{_ as e,o as r,c as a,a2 as n}from"./chunks/framework.BAQ5ZYJQ.js";const p=JSON.parse('{"title":"Tutorials","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/index.md","filePath":"tutorials/index.md","lastUpdated":1792187838000}'),o={name:"tutorials/index.md"};function s(i,t,d,h,l,c){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h1><p>Four walkthroughs. Each one adds a leg, and each one is a directory you can <code>cd</code> into: the first three ship with errand, in <a href="https://github.com/hleclerc/errand/tree/main/examples" target="_blank" rel="noreferrer"><code>examples/</code></a>.</p><p><strong>Which first?</strong> Start where your project is:</p><ul><li>you want to see the <strong>layers</strong> (containers, ssh, Slurm) at work → <a href="./environments">1 · Four environments</a></li><li>a <strong>pytest / Catch2 / cargo</strong> project → <a href="./adopt-a-suite">2 · Adopt an existing suite</a></li><li><strong>no framework</strong>, work to write with errand&#39;s own entries → <a href="./first-entry">4 · errand&#39;s own entries</a></li></ul><table tabindex="0"><thead><tr><th></th><th>what it shows</th><th>needs</th></tr></thead><tbody><tr><td><a href="./environments">1 · Four environments</a></td><td>environments as layer stacks, tags, building them, running in several at once, <code>--batch</code></td><td>reading, mostly</td></tr><tr><td><a href="./adopt-a-suite">2 · Adopt an existing suite</a></td><td>a pytest / Catch2 / cargo project, its tests run one by one, unmodified</td><td>a compiler, cargo</td></tr><tr><td><a href="./two-machines">3 · Numbers over two machines</a></td><td>the whole thing end to end: numbers taken in two places, compared</td><td>an ssh host</td></tr><tr><td><a href="./first-entry">4 · errand&#39;s own entries</a></td><td>no configuration at all: entries, parameters, matrices, the output tree</td><td>nothing but <code>errand</code></td></tr></tbody></table><p>The second and the fourth need nothing but their own toolchain. Tutorials one and three name micromamba environments, Apptainer images, ssh hosts and a Slurm partition that do not exist on your machine — they are there to be read and adapted, and <code>errand envs</code> will tell you honestly that none of them is built.</p><div class="tip custom-block"><p class="custom-block-title">Reading order, if you are in a hurry</p><p>Read <a href="/errand/guide/start">Getting started</a>. Then <a href="/errand/guide/environments">Environments</a> and <a href="/errand/guide/output">Where the output goes</a>, which are the two ideas everything else is built on.</p></div>',7)])])}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
